<?php
class ParkirController{private Parkir $m;function __construct(PDO $pdo){$this->m=new Parkir($pdo);}private function admin(){if(($_SESSION['user_role']??'')!=='admin'){http_response_code(403);exit('Akses hanya untuk admin');}}
function dashboard(){ $aktif=$this->m->countAktif();$hariIni=$this->m->countHariIni();$omzet=$this->m->omzetHariIni();$parkir=$this->m->aktif();include __DIR__.'/../views/dashboard.php';}
function masuk(){ $error='';if($_SERVER['REQUEST_METHOD']==='POST'){ $plat=trim($_POST['plat_nomor']??'');$jenis=$_POST['jenis_roda']??'';if(!preg_match('/^[A-Za-z0-9 -]{3,12}$/',$plat)||!in_array($jenis,['2','4']))$error='Plat nomor dan jenis kendaraan wajib valid';elseif($this->m->cariAktif($plat))$error='Kendaraan ini masih berada di area parkir';else{$this->m->masuk($plat,$jenis);$_SESSION['flash']='Kendaraan berhasil dicatat masuk';header('Location: index.php');exit;}}include __DIR__.'/../views/parkir/masuk.php';}
function keluar(){ $plat=trim($_GET['plat']??'');$hasil=$plat?$this->m->cariAktif($plat):[];include __DIR__.'/../views/parkir/keluar.php';}
function prosesKeluar(){ $this->admin();$id=(int)($_POST['id']??0);$row=$this->m->find($id);if(!$row||$row['status']!=='masuk'){$_SESSION['flash_error']='Data parkir tidak ditemukan';header('Location: index.php?page=keluar');exit;}$jam=max(1,(int)ceil((time()-strtotime($row['waktu_masuk']))/3600));$total=$row['jenis_roda']==='2'?2000+max(0,$jam-1)*1000:5000+max(0,$jam-1)*1000;$this->m->keluar($id,$total);$_SESSION['flash']='Transaksi keluar tersimpan. Total bayar Rp '.number_format($total,0,',','.');header('Location: index.php?page=keluar');exit;}
function laporan(){ $this->admin();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$data=$this->m->laporan($from,$to);if(isset($_GET['csv'])){$this->csv($data,$from,$to);return;}include __DIR__.'/../views/laporan.php';}
private function csv($data,$from,$to){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="laporan-parkir-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['ID','Plat Nomor','Jenis Roda','Waktu Masuk','Waktu Keluar','Status','Total Bayar']);foreach($data as $r)fputcsv($out,[$r['id'],$r['plat_nomor'],$r['jenis_roda'].' roda',$r['waktu_masuk'],$r['waktu_keluar'],$r['status'],$r['total_bayar']]);fclose($out);exit;}}
